'use strict';
document.body.insertAdjacentHTML('beforeend',`<dialog id="usabilityDialog" class="usability-dialog" aria-labelledby="usabilityTitle"><button id="closeUsability" aria-label="Cerrar prueba">✕</button><span class="eyebrow">PROBEMOS JUNTOS</span><h2 id="usabilityTitle">Tres retos con Félicette.</h2><p>No es un examen. Queremos saber qué se entiende y qué podemos mejorar. Podés cerrar esta ventana para explorar y volver después.</p><div id="userTasks"></div><label>¿Qué te confundió o qué cambiarías?<textarea id="userTestComment" rows="3"></textarea></label><button id="downloadUserTest" class="primary">Descargar mis respuestas</button><p class="game-small">Se guarda solo en este navegador. No se envía automáticamente. El equipo todavía necesita realizar y documentar las pruebas con personas.</p></dialog>`);
let study={};try{study=JSON.parse(localStorage.getItem('lunares-usability')||'{}');}catch{}
const tasks=[['Encontrá el lugar con más luz','En El lugar, compará los tres puntos para la misma fecha. Anotá cuál elegiste y por qué.'],['Cambiá la semana','Mantené el mismo sitio y probá otra fecha. Contá qué cambió en luz o comunicación.'],['Interpretá el verde','Explorá el terreno 3D. ¿Qué significa el verde? ¿Alcanza para asegurar un aterrizaje?']];
function saveStudy(){localStorage.setItem('lunares-usability',JSON.stringify(study));}
function renderStudy(){$('userTasks').innerHTML=tasks.map(([name,help],i)=>{const v=study[i]||{};return `<section class="user-task"><span>RETO ${i+1}</span><h3>${name}</h3><p>${help}</p><button data-study-start="${i}">${v.start?'Volver a explorar':'Empezar este reto'}</button><button data-study-end="${i}" ${!v.start?'disabled':''}>Ya lo intenté</button><label>Contanos lo que descubriste<textarea data-study-answer="${i}" rows="2"></textarea></label><small>${v.end?'Tiempo registrado: '+Math.round((v.end-v.start)/1000)+' segundos.':'Podés tomarte el tiempo que necesites.'}</small></section>`;}).join('');document.querySelectorAll('[data-study-answer]').forEach(t=>{t.value=study[t.dataset.studyAnswer]?.answer||'';t.oninput=()=>{const i=t.dataset.studyAnswer;study[i]={...study[i],answer:t.value};saveStudy();};});document.querySelectorAll('[data-study-start]').forEach(b=>b.onclick=()=>{const i=b.dataset.studyStart;if(!study[i]?.start)study[i]={...study[i],start:Date.now()};saveStudy();$('usabilityDialog').close();if($('publicMission').hidden)showAudience('mission');renderStudy();});document.querySelectorAll('[data-study-end]').forEach(b=>b.onclick=()=>{const i=b.dataset.studyEnd;study[i]={...study[i],end:Date.now()};saveStudy();renderStudy();});}
$('closeUsability').onclick=()=>$('usabilityDialog').close();$('userTestComment').value=study.comment||'';$('userTestComment').oninput=e=>{study.comment=e.target.value;saveStudy();};$('downloadUserTest').onclick=()=>download('los-lunares-prueba-de-usabilidad.json',JSON.stringify({prototype:true,method:'Three task self-report; timing includes exploration and pauses; not a controlled study',tasks:tasks.map(([name],i)=>({name,...study[i]})),comment:study.comment||'',source:'LOLA Site01 + NASA SVS',createdUTC:new Date().toISOString()},null,2),'application/json');renderStudy();
function realMethods(){const panel=$('sources');panel.innerHTML=`<section class="panel prose"><span class="eyebrow">PROCEDENCIA Y LÍMITES</span><h2>Qué calcula esta versión.</h2><p>El juego, el laboratorio y la comparación comparten un motor en el navegador: ubicación → elevación LOLA → horizonte local muestreado → direcciones Sol/Tierra → ventanas → balance de panel y batería.</p><table><thead><tr><th>Componente</th><th>Fuente y alcance</th></tr></thead><tbody><tr><td>Terreno</td><td>Site01_final_adj_5mpp_surf.tif del ZIP entregado por el equipo. Solo el original de 16 × 16 km. No se usan los 24 sitios simulados. Radio de referencia 1.737,4 km, estereográfica polar sur.</td></tr><tr><td>Reducción</td><td>DEM nativo 5 m agregado a 20 m: altura media para superficie/observador; altura máxima para horizonte; mayor pendiente nativa para la categoría de cada celda. La malla 3D visual está reducida a ≈80 m.</td></tr><tr><td>Horizonte</td><td>Geometría esférica sin refracción. Muestreo radial 20 m y azimutal 2°, interpolación angular. Radio seleccionable 1–3 km. Fuera de cobertura se rechaza el punto; no se inventan elevaciones.</td></tr><tr><td>Posiciones astronómicas</td><td>NASA SVS 2025/2026, 17.520 muestras horarias. Puntos subsolar/subterrestre, distancia terrestre y geometría esférica con altura del terreno y del observador. Incluye la variación subterrestre asociada a libración. Es una aproximación, no una consulta Horizons/SPICE a demanda.</td></tr><tr><td>Visibilidad</td><td>Confirmada dentro del radio cuando la elevación supera horizonte + margen. Cerca del horizonte se marca marginal. Las horas marginales se tratan conservadoramente como no confirmadas para energía y comunicaciones.</td></tr><tr><td>Próximos eventos</td><td>Primer cambio entre muestras horarias; tiempo aproximado, no instante exacto de puesta. Si no hay cambio en siete días, se informa el límite del período.</td></tr><tr><td>Panel y batería</td><td>Incidencia, área, eficiencia, pérdidas supuestas, demanda y almacenamiento. No se calcula temperatura, eclipses, disco solar, polvo ni operación de una estación terrestre.</td></tr></tbody></table><h3>Qué significa verde</h3><p>Un criterio de pendiente ajustable; no un sitio aprobado para aterrizar. No se resuelven rocas, rugosidad subpíxel, incertidumbre local ni relieve más allá del radio. La capa de altura global es contexto y no clasifica seguridad.</p><h3>Validación y precisión</h3><p id="validationSummary">Las pruebas del paquete verifican proyección, curvatura, cobertura, estados marginales, ventanas y balance. El contraste astronómico con las muestras JPL guardadas se entrega en el informe de validación; no constituye validación de vuelo ni de todos los lugares y fechas.</p><h3>Fuentes</h3><p><a href="https://pgda.gsfc.nasa.gov/products/78" target="_blank" rel="noopener">LOLA: DEM e incertidumbres</a> · <a href="https://svs.gsfc.nasa.gov/5415/" target="_blank" rel="noopener">NASA SVS 2025</a> · <a href="https://svs.gsfc.nasa.gov/5587/" target="_blank" rel="noopener">NASA SVS 2026</a> · <a href="https://ssd.jpl.nasa.gov/horizons/manual.html" target="_blank" rel="noopener">JPL Horizons</a> · <a href="https://svs.gsfc.nasa.gov/4720/" target="_blank" rel="noopener">LOLA global para contexto</a>.</p><p>Los DEM LOLA contienen interpolación; la fuente publica mapas de error que no están incluidos en el ZIP. No propagamos incertidumbre por píxel. El margen angular es un supuesto ajustable, no un intervalo estadístico.</p><h3>Créditos y licencias</h3><p>NASA/GSFC/LOLA y NASA SVS. Textura Clementine de MoonDemo (MIT); modelos Tierra/Sol NASA; model-viewer (Apache 2.0); Three.js r128 y OrbitControls (MIT, incluidos localmente). Félicette: personaje original generado con IA bajo indicaciones del equipo. Interfaz adaptada del dashboard provisto; no incluye su base privada ni credenciales.</p><h3>Prueba con personas</h3><p>Se prepararon tres tareas, registro de respuestas y tiempos. El equipo debe ejecutarlas con usuarios y documentar resultados. No se afirma una validación de usabilidad todavía.</p><button data-open-usability>Abrir los tres retos de feedback</button></section>`;bindRealControls();}
window.addEventListener('real-terrain-ready',()=>{realMethods();document.querySelector('.game-disclosure').textContent='Terreno real de Site01 y geometría NASA aproximada. Solo se confirma el horizonte dentro del radio y resolución indicados. El verde no certifica un aterrizaje; el balance no calcula temperatura ni servicio de radio.';const local=$('terrain').querySelector('.two-col');if(local){const detail=document.createElement('details');detail.className='panel';detail.innerHTML='<summary>Práctica complementaria: fórmula sobre superficie sintética</summary>';local.before(detail);detail.append(local);}const gl=$('globalTerrain');if(gl){const details=document.createElement('details');details.className='panel';details.innerHTML='<summary>Contexto global: altura lunar de baja resolución</summary>';gl.before(details);details.append(gl);}const stale=[...$('terrain').querySelectorAll('section')].find(s=>s.querySelector('h2')?.textContent==='Conexión prevista a datos reales');if(stale)stale.remove();});

window.addEventListener('real-terrain-ready',()=>fetch('assets/site01/validation.json').then(r=>r.json()).then(v=>{const errors=v.astronomyComparison.flatMap(c=>Object.values(c.errors)),max=Math.max(...errors.flatMap(e=>[e.maxAzDeg,e.maxElDeg]));$('validationSummary').textContent=`Contraste de las direcciones calculadas con 50 muestras de dos ubicaciones JPL: diferencia angular máxima ${max.toFixed(6)}°. Las referencias cubren un día; no se extrapola esta precisión a toda ubicación/fecha. También se prueban proyección, curvatura, cobertura, ventanas y estados marginales.`;}).catch(()=>{}));
